import type { Registry } from './types';

export const BARREL_HEADER =
  '// GENERATED by ng-mapcn: rewritten on every `ng-mapcn add`. Do not edit.';

/** Renders `index.ts`: the header plus every public-api export line whose file was copied. */
export function renderBarrel(registry: Registry, present: (file: string) => boolean): string {
  const lines = registry.exports.filter((e) => present(e.file)).map((e) => e.line);
  return [BARREL_HEADER, ...lines].join('\n') + '\n';
}
